-- Resource quiz, verified reviews, Our Story content, approved product
-- previews, and the Nurse Kin launcher (replacing the automatic popup).

-- Resource quiz. Edits go to "draft"; the storefront only ever reads
-- "published", which changes only when the owner presses Publish.
create table if not exists quizzes (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  status text not null default 'draft' check (status in ('draft','published','archived')),
  draft jsonb not null,
  published jsonb,
  version integer not null default 0,
  published_at timestamptz,
  created_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
-- One storefront quiz at a time.
create unique index if not exists quizzes_one_published on quizzes ((status)) where status = 'published';

-- Aggregate counts only: no answers and no visitor identifiers are stored.
create table if not exists quiz_stats (
  quiz_id uuid not null references quizzes(id) on delete cascade,
  version integer not null,
  day date not null,
  starts integer not null default 0,
  completions integer not null default 0,
  product_clicks integer not null default 0,
  primary key (quiz_id, version, day)
);

-- Verified purchase reviews. One per customer per product.
create table if not exists reviews (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id) on delete cascade,
  user_id text not null references "user"(id) on delete cascade,
  rating integer not null check (rating between 1 and 5),
  title text not null,
  body text not null,
  display_name text not null,
  status text not null default 'pending' check (status in ('pending','published','rejected')),
  moderation_reason text not null default '',
  moderated_by text,
  moderated_at timestamptz,
  owner_reply text not null default '',
  owner_reply_at timestamptz,
  report_count integer not null default 0,
  report_reasons text[] not null default '{}',
  reported_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, product_id)
);
create index if not exists reviews_product_idx on reviews(product_id, status);

-- Owner managed page content (Our Story). Draft and published copies.
create table if not exists site_content (
  key text primary key,
  draft jsonb not null default '{}',
  published jsonb,
  published_at timestamptz,
  updated_by text,
  updated_at timestamptz not null default now()
);

-- Product previews: selected sample pages and cropped details are separate,
-- watermarked images the owner approves. Paid files are never used directly.
alter table product_images drop constraint if exists product_images_kind_check;
alter table product_images add constraint product_images_kind_check check (kind in ('gallery','sample','detail'));
alter table product_images add column if not exists approved boolean not null default true;
alter table products add column if not exists whats_included text[] not null default '{}';
alter table products add column if not exists walkthrough_tutorial_id uuid references tutorials(id) on delete set null;

-- Nurse Kin: a launcher the visitor opens, never an automatic popup.
alter table marketing_popup add column if not exists launcher_label text not null default '';

alter table storage_uploads drop constraint if exists storage_uploads_purpose_check;
alter table storage_uploads add constraint storage_uploads_purpose_check
  check (purpose in ('product_image','product_file','tutorial_thumbnail','tutorial_video','banner_image','popup_image','story_portrait'));

insert into schema_migrations (name) values ('005_quiz_reviews_story_previews.sql');

-- Row level security on any new table (the store's server is unaffected).
do $$ declare t record; begin
  for t in select tablename from pg_tables where schemaname = 'public' and not rowsecurity loop
    execute format('alter table public.%I enable row level security', t.tablename);
  end loop;
end $$;

commit;
